-- ============================================
-- 设备管理台账表 + 存储过程
-- 数据库: ZTCloud
-- 说明: 存储设备管理台账数据
-- ============================================

USE [ZTCloud]
GO

-- ============================================
-- 1. 创建表
-- ============================================
IF OBJECT_ID(N'dbo.DeviceLedger', N'U') IS NOT NULL
    DROP TABLE dbo.DeviceLedger;
GO

CREATE TABLE dbo.DeviceLedger
(
    Id                  INT IDENTITY(1,1) PRIMARY KEY,
    SeqNo               INT             NOT NULL,
    DeviceCode          NVARCHAR(50)    NOT NULL,
    DeviceName          NVARCHAR(100)   NOT NULL,
    Specification       NVARCHAR(100)   NULL,
    Brand               NVARCHAR(100)   NULL,
    DeviceStatus        NVARCHAR(20)    NULL,
    UsageScope          NVARCHAR(50)    NULL,
    UsageCategory       NVARCHAR(50)    NULL,
    CurrentDept         NVARCHAR(50)    NULL,
    CurrentLocation     NVARCHAR(100)   NULL,
    CurrentPerson       NVARCHAR(50)    NULL,
    CalibrationDate     NVARCHAR(20)    NULL,
    NextCalibrationDate NVARCHAR(20)    NULL,
    QualificationDate   NVARCHAR(20)    NULL
);
GO

-- ============================================
-- 2. 存储过程: 查询全部
-- ============================================
IF OBJECT_ID(N'dbo.sp_DeviceLedger_QueryAll', N'P') IS NOT NULL
    DROP PROCEDURE dbo.sp_DeviceLedger_QueryAll;
GO

CREATE PROCEDURE dbo.sp_DeviceLedger_QueryAll
AS
BEGIN
    SET NOCOUNT ON;
    SELECT * FROM dbo.DeviceLedger ORDER BY SeqNo;
END
GO

-- ============================================
-- 3. 存储过程: 新增
-- ============================================
IF OBJECT_ID(N'dbo.sp_DeviceLedger_Insert', N'P') IS NOT NULL
    DROP PROCEDURE dbo.sp_DeviceLedger_Insert;
GO

CREATE PROCEDURE dbo.sp_DeviceLedger_Insert
    @SeqNo              INT,
    @DeviceCode         NVARCHAR(50),
    @DeviceName         NVARCHAR(100),
    @Specification      NVARCHAR(100),
    @Brand              NVARCHAR(100),
    @DeviceStatus       NVARCHAR(20),
    @UsageScope         NVARCHAR(50),
    @UsageCategory      NVARCHAR(50),
    @CurrentDept        NVARCHAR(50),
    @CurrentLocation    NVARCHAR(100),
    @CurrentPerson      NVARCHAR(50),
    @CalibrationDate    NVARCHAR(20),
    @NextCalibrationDate NVARCHAR(20),
    @QualificationDate  NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO dbo.DeviceLedger
        (SeqNo, DeviceCode, DeviceName, Specification, Brand,
         DeviceStatus, UsageScope, UsageCategory, CurrentDept,
         CurrentLocation, CurrentPerson,
         CalibrationDate, NextCalibrationDate, QualificationDate)
    VALUES
        (@SeqNo, @DeviceCode, @DeviceName, @Specification, @Brand,
         @DeviceStatus, @UsageScope, @UsageCategory, @CurrentDept,
         @CurrentLocation, @CurrentPerson,
         @CalibrationDate, @NextCalibrationDate, @QualificationDate);
    SELECT SCOPE_IDENTITY() AS NewId;
END
GO

-- ============================================
-- 4. 存储过程: 编辑
-- ============================================
IF OBJECT_ID(N'dbo.sp_DeviceLedger_Update', N'P') IS NOT NULL
    DROP PROCEDURE dbo.sp_DeviceLedger_Update;
GO

CREATE PROCEDURE dbo.sp_DeviceLedger_Update
    @Id                 INT,
    @SeqNo              INT,
    @DeviceCode         NVARCHAR(50),
    @DeviceName         NVARCHAR(100),
    @Specification      NVARCHAR(100),
    @Brand              NVARCHAR(100),
    @DeviceStatus       NVARCHAR(20),
    @UsageScope         NVARCHAR(50),
    @UsageCategory      NVARCHAR(50),
    @CurrentDept        NVARCHAR(50),
    @CurrentLocation    NVARCHAR(100),
    @CurrentPerson      NVARCHAR(50),
    @CalibrationDate    NVARCHAR(20),
    @NextCalibrationDate NVARCHAR(20),
    @QualificationDate  NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE dbo.DeviceLedger SET
        SeqNo               = @SeqNo,
        DeviceCode          = @DeviceCode,
        DeviceName          = @DeviceName,
        Specification       = @Specification,
        Brand               = @Brand,
        DeviceStatus        = @DeviceStatus,
        UsageScope          = @UsageScope,
        UsageCategory       = @UsageCategory,
        CurrentDept         = @CurrentDept,
        CurrentLocation     = @CurrentLocation,
        CurrentPerson       = @CurrentPerson,
        CalibrationDate     = @CalibrationDate,
        NextCalibrationDate = @NextCalibrationDate,
        QualificationDate   = @QualificationDate
    WHERE Id = @Id;
END
GO

-- ============================================
-- 5. 存储过程: 删除
-- ============================================
IF OBJECT_ID(N'dbo.sp_DeviceLedger_Delete', N'P') IS NOT NULL
    DROP PROCEDURE dbo.sp_DeviceLedger_Delete;
GO

CREATE PROCEDURE dbo.sp_DeviceLedger_Delete
    @Id INT
AS
BEGIN
    SET NOCOUNT ON;
    DELETE FROM dbo.DeviceLedger WHERE Id = @Id;
END
GO

-- ============================================
-- 6. 存储过程: 写入操作日志 (跨库写入 ZTCloudData)
-- ============================================
IF OBJECT_ID(N'dbo.sp_DeviceLedger_LogInsert', N'P') IS NOT NULL
    DROP PROCEDURE dbo.sp_DeviceLedger_LogInsert;
GO

CREATE PROCEDURE dbo.sp_DeviceLedger_LogInsert
    @OperationType  NVARCHAR(20),
    @RecordId       INT,
    @DeviceName     NVARCHAR(100),
    @DeviceCode     NVARCHAR(50),
    @Operator       NVARCHAR(50),
    @Details        NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO [ZTCloudData].[dbo].[DeviceLedgerLog]
        (OperationType, RecordId, DeviceName, DeviceCode, Operator, Details)
    VALUES
        (@OperationType, @RecordId, @DeviceName, @DeviceCode, @Operator, @Details);
END
GO

